// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {

	// (GET /api/v1/catalogo/categorias)
	Categorias(ctx context.Context, request CategoriasRequestObject) (CategoriasResponseObject, error)
	// Complementos Los complementarios de lo que hay en el carrito
	// (POST /api/v1/catalogo/complementos)
	Complementos(ctx context.Context, request ComplementosRequestObject) (ComplementosResponseObject, error)
	// ListaVigente Qué lista de precios le toca a quien pide, y cómo se muestran
	// (GET /api/v1/catalogo/lista)
	ListaVigente(ctx context.Context, request ListaVigenteRequestObject) (ListaVigenteResponseObject, error)

	// (GET /api/v1/catalogo/marcas)
	Marcas(ctx context.Context, request MarcasRequestObject) (MarcasResponseObject, error)
	// MiLista Las filas de la lista de precios en PDF, con los precios de quien pide
	// (GET /api/v1/catalogo/mi-lista)
	MiLista(ctx context.Context, request MiListaRequestObject) (MiListaResponseObject, error)

	// (GET /api/v1/catalogo/numeros)
	Numeros(ctx context.Context, request NumerosRequestObject) (NumerosResponseObject, error)

	// (GET /api/v1/catalogo/portada)
	Portada(ctx context.Context, request PortadaRequestObject) (PortadaResponseObject, error)
	// PreciosPorVariante El precio de cada variante para la lista de quien pide (vacío si es la general)
	// (GET /api/v1/catalogo/precios-por-variante)
	PreciosPorVariante(ctx context.Context, request PreciosPorVarianteRequestObject) (PreciosPorVarianteResponseObject, error)
	// Productos El listado filtrado y ordenado
	// (GET /api/v1/catalogo/productos)
	Productos(ctx context.Context, request ProductosRequestObject) (ProductosResponseObject, error)
	// PaginaDeProductos Una página del listado (24 por página, hasta 5 acumuladas)
	// (GET /api/v1/catalogo/productos/pagina)
	PaginaDeProductos(ctx context.Context, request PaginaDeProductosRequestObject) (PaginaDeProductosResponseObject, error)
	// Sugeridos Complementarios y similares de una ficha, a precio de público
	// (GET /api/v1/catalogo/productos/{id}/sugeridos)
	Sugeridos(ctx context.Context, request SugeridosRequestObject) (SugeridosResponseObject, error)
	// Producto La ficha
	// (GET /api/v1/catalogo/productos/{slug})
	Producto(ctx context.Context, request ProductoRequestObject) (ProductoResponseObject, error)

	// (GET /api/v1/catalogo/rubros)
	Rubros(ctx context.Context, request RubrosRequestObject) (RubrosResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

